cd /workspace && node -e "
const XLSX = require('xlsx');
const filePath = 'testbed/data/travel_expenses.xlsx';

// Read the workbook
const wb = XLSX.readFile(filePath);

// Verify 'Travel' sheet exists
if (!wb.SheetNames.includes('Travel')) {
  console.log('Available sheets:', wb.SheetNames);
  process.exit(1);
}

const ws = wb.Sheets['Travel'];

// Write 129 at row 43, column 7 (G43)
const cellRef = XLSX.utils.encode_cell({ r: 42, c: 6 }); // 0-indexed
ws[cellRef] = { t: 'n', v: 129 };

// Update the sheet range if needed
const range = XLSX.utils.decode_range(ws['!ref'] || 'A1');
if (42 > range.e.r) range.e.r = 42;
if (6 > range.e.c) range.e.c = 6;
ws['!ref'] = XLSX.utils.encode_range(range);

// Save the workbook
XLSX.writeFile(wb, filePath);
console.log('Successfully wrote 129 to cell G43 in the Travel sheet.');
"

